-			      sizeof(res));
+	rc = regmap_bulk_read(data->regmap, VCNL_PS_RESULT_HI, &data->buf,
+			      sizeof(data->buf));
 	if (rc)
 		goto err_unlock;

-	*val = be16_to_cpu(res);
+	*val = be16_to_cpu(data->buf);

 err_unlock:
