+		.event_spec = vcnl3020_event_spec,
+		.num_event_specs = ARRAY_SIZE(vcnl3020_event_spec),
 	},
 };

@@ -251,17 +504,11 @@ static int vcnl3020_write_raw(struct iio_dev *indio_dev,
